package ru.neverland.townytaxes.command;

import com.palmergames.bukkit.towny.object.Resident;
import com.palmergames.bukkit.towny.object.Town;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.jetbrains.annotations.NotNull;
import ru.neverland.townytaxes.integration.TownyHook;
import ru.neverland.townytaxes.model.Domain;
import ru.neverland.townytaxes.model.TaxPolicy;
import ru.neverland.townytaxes.service.FiscalService;
import ru.neverland.townytaxes.service.MessageService;
import ru.neverland.townytaxes.util.ColorUtil;

import java.util.Map;

public final class TownTaxesCommand implements CommandExecutor {
    private final TownyHook towny;private final FiscalService fiscal;private final MessageService messages;
    public TownTaxesCommand(TownyHook towny,FiscalService fiscal,MessageService messages){this.towny=towny;this.fiscal=fiscal;this.messages=messages;}
    @Override public boolean onCommand(@NotNull CommandSender sender,@NotNull Command command,@NotNull String label,@NotNull String[] args){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyTaxes")){return true;}if(!(sender instanceof Player player)){messages.send(sender,"players-only");return true;}if(!player.hasPermission("townytaxes.use")){messages.send(player,"no-permission");return true;}String action=args.length==0?label.equalsIgnoreCase("mytaxes")?"preview":"":args[0].toLowerCase(java.util.Locale.ROOT);if(action.equals("preview")||action.equals("receipts")){try{if(action.equals("preview"))preview(player,args);else receipts(player);}catch(Exception error){player.sendMessage(ColorUtil.color("&e"+error.getMessage()));}return true;}Town town=towny.town(player);if(town==null){messages.send(player,"no-town");return true;}if(args.length==0||args[0].equalsIgnoreCase("help")){status(player,town);return true;}try{switch(args[0].toLowerCase(java.util.Locale.ROOT)){case"policies","list"->list(player,town);case"create"->create(player,town,args);case"remove"->remove(player,town,args);case"debt"->debt(player,town);case"pay"->pay(player);default->messages.list("help-taxes").forEach(player::sendMessage);}}catch(Exception error){player.sendMessage(ColorUtil.color("&e"+error.getMessage()));}return true;} }
    private void status(Player p,Town t){p.sendMessage(ColorUtil.color("&#FFD45A&lКазначейство города "+t.getName()));if(fiscal.economyReady()){try{var account=towny.account(t::getAccount);if(account!=null)p.sendMessage(ColorUtil.color("&7Баланс города: &f"+fiscal.format(account.getHoldingBalance())));else messages.send(p,"economy-unavailable");}catch(RuntimeException unavailable){messages.send(p,"economy-unavailable");}}else messages.send(p,"economy-unavailable");Resident r=towny.resident(p);try{p.sendMessage(ColorUtil.color("&7Ваша задолженность: &f"+fiscal.format(r==null?0:fiscal.taxDebt(r.getUUID()))));}catch(IllegalStateException waiting){p.sendMessage(ColorUtil.color("&7Задолженность уточняется: налоговый учёт ещё недоступен."));}p.sendMessage(ColorUtil.color("&7Городских сборов: &f"+fiscal.repository().policies().stream().filter(v->v.scope()==Domain.Scope.TOWN&&v.targetId().equals(t.getUUID())).count()));messages.list("help-taxes").forEach(p::sendMessage);p.sendMessage(ColorUtil.color("&f/mytaxes preview [доход] [перевод] &7— точный расчёт; /mytaxes receipts — личные квитанции."));}
    private void list(Player p,Town t){p.sendMessage(ColorUtil.color("&#FFD45A&lГородские налоговые сборы:"));boolean any=false;for(TaxPolicy v:fiscal.repository().policies())if(v.scope()==Domain.Scope.TOWN&&v.targetId().equals(t.getUUID())){any=true;p.sendMessage(ColorUtil.color("&8- &f"+v.shortId()+" &7"+taxName(v.type())+": &e"+v.value()+(v.type()==Domain.TaxType.FIXED?" монет":"%")+" &8→ &f"+v.destinationName()+(ru.neverland.townytaxes.model.MunicipalTaxes.matches(v,t.getUUID())?" &7(по указу: &e"+fiscal.format(v.value()*ru.neverland.integration.PoliciesAccess.tax(t.getUUID()))+(v.type()==Domain.TaxType.FIXED?" монет":"%")+"&7; до санкций и соглашений)":"")));}if(!any)p.sendMessage(ColorUtil.color("&7Сборы не настроены."));}
    private void create(Player p,Town t,String[] a){if(!p.hasPermission("townytaxes.manage")||!towny.isTownManager(p,t,"tax")){messages.send(p,"only-town-manager");return;}if(a.length<3){p.sendMessage(ColorUtil.color("&fИспользование: /t taxes create <fixed|income|transaction> <значение> [интервал в минутах]"));return;}Domain.TaxType type=Domain.TaxType.parse(a[1]);if(type==null){messages.send(p,"invalid-tax-type");return;}try{double value=Double.parseDouble(a[2].replace(',','.'));if(!fiscal.validTaxValue(type,value))throw new NumberFormatException();long minutes=a.length>3?Long.parseLong(a[3]):1440;TownyHook.Party party=new TownyHook.Party(Domain.Scope.TOWN,t.getUUID(),t.getName(),towny.account(t::getAccount));TaxPolicy policy=fiscal.createPolicy(party,type,value,party,fiscal.intervalMillis(minutes),p.getName());messages.send(p,"policy-created",Map.of("id",policy.shortId()));}catch(NumberFormatException e){messages.send(p,"invalid-number");}}
    private void remove(Player p,Town t,String[] a){if(!p.hasPermission("townytaxes.manage")||!towny.isTownManager(p,t,"tax")){messages.send(p,"only-town-manager");return;}if(a.length<2){p.sendMessage("/t taxes remove <ID>");return;}TaxPolicy v=fiscal.repository().policy(a[1]);if(v==null||v.scope()!=Domain.Scope.TOWN||!v.targetId().equals(t.getUUID())){messages.send(p,"policy-not-found",Map.of("id",a[1]));return;}fiscal.removePolicy(a[1]);messages.send(p,"policy-removed",Map.of("id",v.shortId()));}
    private void debt(Player p,Town t){Resident r=towny.resident(p);p.sendMessage(ColorUtil.color("&#FFD45AЗадолженность игрока: &f"+fiscal.format(r==null?0:fiscal.taxDebt(r.getUUID()))+"\n&#FFD45AЗадолженность города: &f"+fiscal.format(fiscal.taxDebt(t.getUUID()))));}
    private void pay(Player p){if(!fiscal.economyReady()){messages.send(p,"economy-unavailable");return;}Resident r=towny.resident(p);if(r!=null&&fiscal.payDebt(new TownyHook.Party(Domain.Scope.PLAYER,r.getUUID(),r.getName(),towny.account(r::getAccount))))p.sendMessage(ColorUtil.color("&aПогашение принято к обработке. Итог будет в /mytaxes receipts; неизвестный результат повторно не оплачивается."));else messages.send(p,"tax-debt",Map.of("amount",fiscal.format(r==null?0:fiscal.taxDebt(r.getUUID()))));}
    private static long previewAmount(String text){try{long cents=new java.math.BigDecimal(text.replace(',','.')).movePointRight(2).longValueExact();if(cents<0||cents>ru.neverland.townytaxes.model.TaxCalculation.MAX_CENTS)throw new IllegalArgumentException();return cents;}catch(Exception error){throw new IllegalArgumentException("Укажите неотрицательную сумму с точностью до копейки");}}
    private void preview(Player player,String[] args){
        if(args.length>3)throw new IllegalArgumentException("/mytaxes preview [пример дохода] [пример перевода]");long income=args.length>1?previewAmount(args[1]):10000,transfer=args.length>2?previewAmount(args[2]):income;
        player.sendMessage(ColorUtil.color("&#FFD45A&lВаш предварительный расчёт налогов"));player.sendMessage(ColorUtil.color("&7Пример дохода: "+fiscal.format(income/100.0)+"; входящего перевода: "+fiscal.format(transfer/100.0)+". Расчёт ничего не списывает."));
        var rows=fiscal.taxPreview(player.getUniqueId(),income,transfer);if(rows.isEmpty())player.sendMessage(ColorUtil.color("&7Применимых налогов сейчас нет."));
        var date=java.time.format.DateTimeFormatter.ofPattern("dd.MM HH:mm").withZone(java.time.ZoneId.of("Europe/Moscow"));
        for(var row:rows){player.sendMessage(ColorUtil.color("&e"+taxName(Domain.TaxType.valueOf((String)row.get("type")))+" &7"+row.get("policy").toString().substring(0,8)+" → "+row.get("destination")));player.sendMessage(ColorUtil.color("&f"+row.get("description")));if(row.get("type").equals("FIXED"))player.sendMessage(ColorUtil.color("&7Ближайший сбор: "+date.format(java.time.Instant.ofEpochMilli(((Number)row.get("next")).longValue()))+" МСК; при паузе экономики сроки переносятся без штрафов."));}
    }
    private void receipts(Player player){
        player.sendMessage(ColorUtil.color("&#FFD45A&lВаши налоговые квитанции"));var rows=fiscal.taxReceipts(player.getUniqueId());if(rows.isEmpty())player.sendMessage(ColorUtil.color("&7Новых квитанций пока нет."));
        int count=0;for(var row:rows){if(count++>=10)break;player.sendMessage(ColorUtil.color("&e"+row.get("id").toString().substring(0,8)+" &f"+fiscal.format(((Number)row.get("cents")).longValue()/100.0)+" → "+row.get("destination")+" &7• "+FiscalService.paymentState((String)row.get("phase"))));player.sendMessage(ColorUtil.color("&7"+row.get("description")));}
    }
    private String taxName(Domain.TaxType t){return switch(t){case FIXED->"фиксированный";case INCOME->"подоходный";case TRANSACTION->"транзакционный";};}
}
